// Generates the Dart bindings of the Go core from its C contract,
// core/include/chatcore.h. Never edit the generated file by hand.
//
// Run from app/: dart run tool/ffigen.dart
import 'dart:io';

import 'package:ffigen/ffigen.dart';

Future<void> main() async {
  final packageRoot = Platform.script.resolve('../');
  await FfiGenerator(
    input: Input(
      entryPoints: [packageRoot.resolve('../core/include/chatcore.h')],
    ),
    output: Output(
      dart: DartOutput(
        path: packageRoot.resolve('lib/src/core_bridge/chatcore.g.dart'),
      ),
      // Must match the asset name registered by hook/build.dart.
      style: const NativeExternalBindings(
        assetId: 'package:chat_do_garoto/src/core_bridge/chatcore.g.dart',
      ),
      preamble: '''
// Generated by package:ffigen from core/include/chatcore.h. Do not edit.
// To regenerate, run from app/: dart run tool/ffigen.dart

// ignore_for_file: type=lint
''',
    ),
    visitors: [
      Visitor(func: (node) => node.isIncluded = node.name.startsWith('cc_')),
    ],
  ).generate();
}
